mapper.select:
SELECT * FROM ui_flows

    AND app_id = #{appId}
    AND platform = #{platform}
    AND catalog = #{catalog}
    AND COALESCE(environment, 'PROD') = #{environment}
    AND is_component = 1
    AND name LIKE CONCAT('%', #{name}, '%')

ORDER BY sort_order ASC, updated_at DESC

SELECT * FROM ui_flows
WHERE enabled = 1
  AND (is_component = 0 OR is_component IS NULL)
  AND catalog IN


          #{c}

      ('ONLINE', 'SHARED')




      AND COALESCE(release_stage, 'ONLINE') = 'ONLINE'

  AND (catalog = 'AUTOMATION'
       OR env_bound = 0
       OR COALESCE(environment, 'PROD') =

              #{environment}
              'PROD'
          )


      AND (
          app_id = #{appId}
          OR ((app_id IS NULL OR app_id = '') AND catalog = 'SHARED')

              OR ((app_id IS NULL OR app_id = '') AND catalog = 'ONLINE')

      )

  AND platform = #{platform}
ORDER BY sort_order ASC, name ASC
